import{_ as e,o as a,c as s,a1 as o}from"./chunks/framework.BKrM4vFX.js";const h=JSON.parse('{"title":"RFC-001. Изоляция песочниц для публичного мока","description":"RFC-001. Изоляция песочниц для публичного мока. © 2026 ООО «Аксиома» ИНН:7842223709 · https://github.com/rucorp/mock-services · все права защищены Документ проекта mock-services (оригинал: rucorp/mock-services). Статус: реализовано в #8 (закрывает A-21, F-11—F-15): re","frontmatter":{"sourcePath":"docs/rfc/RFC-001-multi-tenant-sandboxes.md"},"headers":[{"level":1,"title":"RFC-001. Изоляция песочниц для публичного мока","slug":"rfc-001-Изоляция-песочниц-для-публичного-мока","link":"#rfc-001-Изоляция-песочниц-для-публичного-мока","children":[{"level":2,"title":"1. Проблема","slug":"_1-Проблема","link":"#_1-Проблема","children":[]},{"level":2,"title":"2. Цели и не-цели","slug":"_2-Цели-и-не-цели","link":"#_2-Цели-и-не-цели","children":[]},{"level":2,"title":"3. Ключевая развилка: как клиент идентифицирует песочницу","slug":"_3-Ключевая-развилка-как-клиент-идентифицирует-песочницу","link":"#_3-Ключевая-развилка-как-клиент-идентифицирует-песочницу","children":[]},{"level":2,"title":"4. Модель данных","slug":"_4-Модель-данных","link":"#_4-Модель-данных","children":[]},{"level":2,"title":"5. Маршрутизация","slug":"_5-Маршрутизация","link":"#_5-Маршрутизация","children":[]},{"level":2,"title":"6. Публичный API управления песочницами","slug":"_6-Публичный-api-управления-песочницами","link":"#_6-Публичный-api-управления-песочницами","children":[]},{"level":2,"title":"7. Безопасность","slug":"_7-Безопасность","link":"#_7-Безопасность","children":[]},{"level":2,"title":"8. Эксплуатация","slug":"_8-Эксплуатация","link":"#_8-Эксплуатация","children":[]},{"level":2,"title":"9. План внедрения (этапы)","slug":"_9-План-внедрения-этапы","link":"#_9-План-внедрения-этапы","children":[]},{"level":2,"title":"10. Открытые вопросы","slug":"_10-Открытые-вопросы","link":"#_10-Открытые-вопросы","children":[]}]}],"relativePath":"docs/rfc/RFC-001-multi-tenant-sandboxes.md","filePath":"docs/rfc/RFC-001-multi-tenant-sandboxes.md"}'),c={name:"docs/rfc/RFC-001-multi-tenant-sandboxes.md"};function n(d,t,i,l,r,p){return a(),s("div",null,[...t[0]||(t[0]=[o(`<p>© 2026 ООО «Аксиома» ИНН:7842223709 · <a href="https://github.com/rucorp/mock-services" target="_blank" rel="noreferrer">https://github.com/rucorp/mock-services</a> · все права защищены Документ проекта mock-services (оригинал: rucorp/mock-services).</p><h1 id="rfc-001-Изоляция-песочниц-для-публичного-мока" tabindex="-1">RFC-001. Изоляция песочниц для публичного мока <a class="header-anchor" href="#rfc-001-Изоляция-песочниц-для-публичного-мока" aria-label="Permalink to &quot;RFC-001. Изоляция песочниц для публичного мока&quot;">​</a></h1><nav class="doc-static-toc" aria-label="Оглавление"><p class="doc-static-toc__title">Оглавление</p><ul><li class="doc-static-toc__item doc-static-toc__item--1"><a class="doc-static-toc__link" href="#rfc-001-Изоляция-песочниц-для-публичного-мока">RFC-001. Изоляция песочниц для публичного мока</a></li><li class="doc-static-toc__item doc-static-toc__item--2"><a class="doc-static-toc__link" href="#_1-Проблема">1. Проблема</a></li><li class="doc-static-toc__item doc-static-toc__item--2"><a class="doc-static-toc__link" href="#_2-Цели-и-не-цели">2. Цели и не-цели</a></li><li class="doc-static-toc__item doc-static-toc__item--2"><a class="doc-static-toc__link" href="#_3-Ключевая-развилка-как-клиент-идентифицирует-песочницу">3. Ключевая развилка: как клиент идентифицирует песочницу</a></li><li class="doc-static-toc__item doc-static-toc__item--2"><a class="doc-static-toc__link" href="#_4-Модель-данных">4. Модель данных</a></li><li class="doc-static-toc__item doc-static-toc__item--2"><a class="doc-static-toc__link" href="#_5-Маршрутизация">5. Маршрутизация</a></li><li class="doc-static-toc__item doc-static-toc__item--2"><a class="doc-static-toc__link" href="#_6-Публичный-api-управления-песочницами">6. Публичный API управления песочницами</a></li><li class="doc-static-toc__item doc-static-toc__item--2"><a class="doc-static-toc__link" href="#_7-Безопасность">7. Безопасность</a></li><li class="doc-static-toc__item doc-static-toc__item--2"><a class="doc-static-toc__link" href="#_8-Эксплуатация">8. Эксплуатация</a></li><li class="doc-static-toc__item doc-static-toc__item--2"><a class="doc-static-toc__link" href="#_9-План-внедрения-этапы">9. План внедрения (этапы)</a></li><li class="doc-static-toc__item doc-static-toc__item--2"><a class="doc-static-toc__link" href="#_10-Открытые-вопросы">10. Открытые вопросы</a></li></ul></nav><blockquote><p>Статус: <strong>реализовано в #8</strong> (закрывает A-21, F-11—F-15): request-local контекст, hosted tenancy за env-флагом, owner-token, target export/import, TTL/лимиты/квоты (§9.1–9.4) · Дата: 2026-10-08 · Связано: аудит 2026-10-08 (§3.2, дефект A-21; материалы — в приватном репозитории команды)</p><p>Вне объёма #8 остались: лендинг/hosted-конфиг (§9.5), <code>/admin</code>-поддомены и браузерные <code>SuccessURL/FailURL</code> в поддоменной схеме, per-sandbox сценарные правила (<code>/sandboxes/me/scenarios</code>) — см. §10 «Открытые вопросы».</p></blockquote><h2 id="_1-Проблема" tabindex="-1">1. Проблема <a class="header-anchor" href="#_1-Проблема" aria-label="Permalink to &quot;1. Проблема&quot;">​</a></h2><p>Сейчас у стенда одно глобальное состояние: один терминал/касса, один реестр <code>external_id</code>, один <code>/admin</code>. Для self-hosted это правильно. Для публичного хостинга это ломается сразу:</p><ul><li>два интегратора пересекаются на <code>external_id</code> (второй получает «документ уже существует» — ошибка 12, хотя у него свой чек);</li><li>чужой <code>PaymentId</code>/<code>uuid</code> читается <code>GetState</code>/<code>report</code>, потому что авторизация — только подпись терминала, а терминал общий;</li><li><code>/admin</code> показывает чужие платежи, а <code>/admin/action</code> управляет чужой кассой;</li><li>один пользователь может «засорить» состояние (гигантские чеки, миллион документов) и замедлить всех.</li></ul><h2 id="_2-Цели-и-не-цели" tabindex="-1">2. Цели и не-цели <a class="header-anchor" href="#_2-Цели-и-не-цели" aria-label="Permalink to &quot;2. Цели и не-цели&quot;">​</a></h2><p><strong>Цели</strong></p><ol><li>Каждый пользователь (или каждая команда) получает <strong>изолированную песочницу</strong> со своими кредами и своим состоянием.</li><li>Песочница создаётся <strong>без регистрации</strong> (демо) или по токену (команды).</li><li>Всё живёт ограниченное время (TTL) и очищается автоматически; есть явный <code>reset</code>.</li><li>Self-hosted режим не усложняется: флагом <code>MOCK_TENANCY=off</code> (по умолчанию) поведение остаётся сегодняшним (одна песочница = весь стенд).</li><li>Соблюдение протокола: клиент по-прежнему ходит на «как у банка» пути; ничего в контракте не меняется (никаких <code>/sandbox/abc/v2/Init</code>, иначе сниппеты интеграторов перестают переноситься на бой).</li></ol><p><strong>Не-цели</strong></p><ul><li>Биллинг, роли, SSO, квоты «по договору» — вне рамок.</li><li>Долговременное хранение данных пользователя; песочницы по определению эфемерны.</li></ul><h2 id="_3-Ключевая-развилка-как-клиент-идентифицирует-песочницу" tabindex="-1">3. Ключевая развилка: как клиент идентифицирует песочницу <a class="header-anchor" href="#_3-Ключевая-развилка-как-клиент-идентифицирует-песочницу" aria-label="Permalink to &quot;3. Ключевая развилка: как клиент идентифицирует песочницу&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Вариант</th><th>Пример</th><th>Плюсы</th><th>Минусы</th></tr></thead><tbody><tr><td><strong>A. Поддомен</strong> (рекомендуемый)</td><td><code>https://&lt;id&gt;.mock-services.dev/v2/Init</code></td><td>Ноль изменений в путях и параметрах; работает с любой библиотекой; естественно для hosted</td><td>Нужен wildcard-DNS и wildcard-сертификат</td></tr><tr><td>B. Заголовок</td><td><code>X-Mock-Sandbox: &lt;id&gt;</code> + обычный хост</td><td>Просто; локально удобно</td><td>Заголовок придётся добавлять всем клиентам/сниппетам; не видно в браузерных редиректах</td></tr><tr><td>C. Базовый путь</td><td><code>/s/&lt;id&gt;/v2/Init</code></td><td>Просто в реализации</td><td>Ломает переносимость сниппетов на бой (в проде пути другие)</td></tr><tr><td>D. Отдельный порт/инстанс на песочницу</td><td><code>:3100X</code></td><td>Полная изоляция процессов</td><td>Дорого и неудобно для пользователя</td></tr></tbody></table><p><strong>Решение:</strong> A (поддомен) как основной способ на hosted; B — как эквивалент для self-hosted и для тестов (заголовок имеет приоритет над поддоменом). C — не использовать.</p><h2 id="_4-Модель-данных" tabindex="-1">4. Модель данных <a class="header-anchor" href="#_4-Модель-данных" aria-label="Permalink to &quot;4. Модель данных&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Sandbox {</span></span>
<span class="line"><span>  id            // &quot;swift-fox-42&quot; (человекочитаемый) или ksuid</span></span>
<span class="line"><span>  createdAt, expiresAt</span></span>
<span class="line"><span>  ownerToken    // доступ к /admin, reset, экспорту (выдаётся при создании)</span></span>
<span class="line"><span>  profile       // &quot;tbank-eacq&quot; | &quot;tbank-multisplit&quot; | &quot;ferma&quot; | ...</span></span>
<span class="line"><span>  creds: {      // креды песочницы: интегратор вписывает их в свою конфигурацию</span></span>
<span class="line"><span>    terminalKey, terminalPassword,</span></span>
<span class="line"><span>    fermaLogin, fermaPassword, fermaGroup</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>  state         // ровно тот же state, что сейчас: payments/deals/notifications/receipts/...</span></span>
<span class="line"><span>  quota: { rps, maxDocuments, maxBodyBytes, ttlMs }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Хранение: один JSON-файл на песочницу (<code>/data/sandboxes/&lt;id&gt;.json</code>) либо встроенная карта в памяти с периодическим дампом. Внешняя БД для демо-стенда не нужна — состояние маленькое и эфемерное.</p><p><strong>Креды генерируются на песочницу.</strong> Это важнее, чем кажется: подпись Т-Банка зависит от пароля терминала, поэтому интегратор проходит ровно тот же путь, что в бою («впиши свой ключ и пароль»), а не «используй общий».</p><h2 id="_5-Маршрутизация" tabindex="-1">5. Маршрутизация <a class="header-anchor" href="#_5-Маршрутизация" aria-label="Permalink to &quot;5. Маршрутизация&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>POST /v2/Init  (Host: swift-fox-42.mock-services.dev)</span></span>
<span class="line"><span>  → resolveSandbox(host | X-Mock-Sandbox)</span></span>
<span class="line"><span>  → если песочницы нет: 404 + подсказка «создайте песочницу: POST /sandboxes»</span></span>
<span class="line"><span>  → state = sandbox.state, creds = sandbox.creds</span></span>
<span class="line"><span>  → адаптер обрабатывает запрос как обычно (контракт не меняется)</span></span></code></pre></div><p>Адаптеры получают <code>sandbox</code> как контекст. Сейчас <code>state</code>, <code>TERMINAL_KEY</code>, <code>TERMINAL_PASSWORD</code> — модульные константы; рефакторинг: «фабрика сервиса» (<code>createServer(ctx)</code>) вместо модульных синглтонов. Ядро уже готово (все механизмы принимают <code>state</code>/<code>persist</code> параметрами), поэтому переделка локализована в <code>services/*/server.js</code>.</p><h2 id="_6-Публичный-api-управления-песочницами" tabindex="-1">6. Публичный API управления песочницами <a class="header-anchor" href="#_6-Публичный-api-управления-песочницами" aria-label="Permalink to &quot;6. Публичный API управления песочницами&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>POST /sandboxes                 → { id, url, ownerToken, creds, expiresAt }</span></span>
<span class="line"><span>GET  /sandboxes/me              → текущая песочница (по ownerToken)</span></span>
<span class="line"><span>POST /sandboxes/me/reset        → очистить состояние (креды сохраняются)</span></span>
<span class="line"><span>POST /sandboxes/me/reset-creds  → сменить креды (проверка «а что если ключ протух»)</span></span>
<span class="line"><span>POST /sandboxes/me/scenarios    → сценарный API (см. §3.3 аудита)</span></span>
<span class="line"><span>DELETE /sandboxes/me            → удалить песочницу немедленно</span></span>
<span class="line"><span>GET  /admin?token=ownerToken    → консоль песочницы (единственная точка, где нужен токен)</span></span></code></pre></div><p>Плюс лендинг (<code>/</code>) с кнопкой «Создать песочницу» и краткой инструкцией «интеграция за 10 минут».</p><p><strong>Источники owner-token</strong> (порядок закреплён задачей #98): <code>X-Sandbox-Token</code> → <code>X-Owner-Token</code> → <code>Authorization: Bearer</code> → <code>?sandbox_token=</code>. Явный заголовок приоритетнее Bearer: у адаптеров, чей бизнес-контракт сам использует <code>Authorization: Bearer &lt;токен&gt;</code> (Первый ОФД — токен очереди, ВТБ — OAuth <code>access_token</code>), Bearer иначе затенял бы owner-token владельца и бизнес-вызов отвечал бы 401. Bearer сохранён как fallback для клиентов, не шлющих явных заголовков; источник с пустым значением считается отсутствующим.</p><h2 id="_7-Безопасность" tabindex="-1">7. Безопасность <a class="header-anchor" href="#_7-Безопасность" aria-label="Permalink to &quot;7. Безопасность&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Угроза</th><th>Мера</th></tr></thead><tbody><tr><td>Перебор чужих песочниц</td><td>id ≥ 96 бит энтропии (или ksuid), rate limit на создание; <code>ownerToken</code> — отдельный секрет, не выводимый из id</td></tr><tr><td>Чтение чужого состояния</td><td>Все API-вызовы работают только в контексте песочницы; <code>/admin</code> — по <code>ownerToken</code></td></tr><tr><td>SSRF через вебхуки</td><td><code>MOCK_BLOCK_PRIVATE_WEBHOOKS=1</code> по умолчанию на hosted + egress-фильтр + запрет редиректов на приватные адреса</td></tr><tr><td>CSRF на админ-действиях</td><td>cookie <code>SameSite=Strict</code>/<code>HttpOnly</code> + CSRF-токен, либо только header-token</td></tr><tr><td>DoS</td><td>quota: RPS на песочницу, лимит тела (5 МБ уже есть), лимит документов и очереди вебхуков, TTL состояния, «вес» вебхука (таймаут 10 с, ≤ 24 попытки)</td></tr><tr><td>Утечка «реальных» данных</td><td>Дисклеймер + запрет нереальных карт (список тестовых PAN), PAN не хранится в открытом виде, журнал ограничен по объёму</td></tr><tr><td>Абьюз как публичный прокси</td><td>egress-фильтр инфраструктуры, allowlist портов (80/443), запрет не-HTTP схем</td></tr></tbody></table><h2 id="_8-Эксплуатация" tabindex="-1">8. Эксплуатация <a class="header-anchor" href="#_8-Эксплуатация" aria-label="Permalink to &quot;8. Эксплуатация&quot;">​</a></h2><ul><li><strong>TTL:</strong> демо-песочницы — 24 ч, командные — 7 дней (настраивается). По истечении: «заморозка» → удаление. Пользователю — письмо/баннер заранее (если есть e-mail; иначе — только баннер в <code>/admin</code>).</li><li><strong>Автоочистка:</strong> фоновый воркер раз в минуту удаляет просроченные песочницы и пустые файлы.</li><li><strong>Метрики:</strong> количество песочниц, RPS, размер состояний, ошибки 4xx/5xx, длина очередей вебхуков (Prometheus <code>/metrics</code> приватно).</li><li><strong>Резервные копии:</strong> не нужны (данные эфемерны), но конфигурация и лимиты — в env/манифесте.</li></ul><h2 id="_9-План-внедрения-этапы" tabindex="-1">9. План внедрения (этапы) <a class="header-anchor" href="#_9-План-внедрения-этапы" aria-label="Permalink to &quot;9. План внедрения (этапы)&quot;">​</a></h2><ol><li><strong>Рефакторинг адаптеров в фабрики</strong> (<code>createBankMock(ctx)</code>, <code>createKassaMock(ctx)</code>), self-hosted поведение не меняется; тесты остаются зелёными. ≈ 1–2 дня.</li><li><strong>Слой песочниц</strong>: реестр, <code>resolveSandbox</code>, генерация кредов, <code>/sandboxes*</code>. ≈ 2 дня.</li><li><strong>Admin-scoped</strong>: <code>/admin</code> по <code>ownerToken</code>, действия только внутри песочницы. ≈ 0.5 дня.</li><li><strong>Quota/лимиты/TTL/автоочистка.</strong> ≈ 1 день.</li><li><strong>Лендинг + доки + hosted-конфиг (wildcard DNS/TLS, egress).</strong> ≈ 1–2 дня.</li></ol><h2 id="_10-Открытые-вопросы" tabindex="-1">10. Открытые вопросы <a class="header-anchor" href="#_10-Открытые-вопросы" aria-label="Permalink to &quot;10. Открытые вопросы&quot;">​</a></h2><ol><li>Демо-песочницы без регистрации — как защититься от массового создания (капча, лимит по IP, «очередь»)? Предложение: лимит 3 песочницы/IP/сутки.</li><li>Нужен ли «общий read-only стенд» для лендинга (демо без создания), или создание песочницы — единственный вход?</li><li>Хотим ли мы поддержать «принеси свой домен» для вебхуков (когда стенд должен звать <code>https://my-app.example/...</code> — это уже работает, но требует egress-разрешений)?</li><li>Как быть с браузерным редиректом <code>SuccessURL/FailURL</code> в поддоменной схеме — разрешать только https из соображений безопасности?</li></ol>`,34)])])}const u=e(c,[["render",n]]);export{h as __pageData,u as default};
